export const stockMovements = sqliteTable('stock_movements', {
  id: text('id').primaryKey(),
  partId: text('part_id').notNull().references(() => parts.id),
  quantityDelta: integer('quantity_delta', { mode: 'number' }).notNull(), // positive or negative
  reason: text('reason', { enum: ['sale', 'void', 'order_receive', 'manual_correction', 'backorder_receive', 'repair_use', 'return', 'waste', 'initial_stock', 'adjustment'] }).notNull(),
